import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Qwen-VLA: Unifying Vision-Language-Action Modeling across Tasks, Environments, and Robot Embodiments","description":"","frontmatter":{"title":"Qwen-VLA: Unifying Vision-Language-Action Modeling across Tasks, Environments, and Robot Embodiments","arxiv":"2605.30280","date":"2026-05-28","authors":"Qiuyue Wang, Mingsheng Li, Jian Guan, Jinhui Ye, Sicheng Xie, Yitao Liu, Junhao Chen, Zhixuan Liang, Jie Zhang, et al.","categories":"cs.RO, cs.AI, cs.CL","topics":"通用具身智能, VLA 统一建模, 跨本体迁移","outline":[2,2]},"headers":[],"relativePath":"papers/2605.30280.md","filePath":"papers/2605.30280.md","lastUpdated":null}'),e={name:"papers/2605.30280.md"};function l(i,s,r,m,o,c){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="qwen-vla-unifying-vision-language-action-modeling-across-tasks-environments-and-robot-embodiments" tabindex="-1">Qwen-VLA: Unifying Vision-Language-Action Modeling across Tasks, Environments, and Robot Embodiments <a class="header-anchor" href="#qwen-vla-unifying-vision-language-action-modeling-across-tasks-environments-and-robot-embodiments" aria-label="Permalink to &quot;Qwen-VLA: Unifying Vision-Language-Action Modeling across Tasks, Environments, and Robot Embodiments&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.30280" target="_blank" rel="noreferrer">2605.30280</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-05-28</td></tr><tr><td><strong>作者</strong></td><td>Qiuyue Wang, Mingsheng Li, Jian Guan, Jinhui Ye, Sicheng Xie, Yitao Liu, Junhao Chen, Zhixuan Liang, Jie Zhang, et al.（共 40 位）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CL</td></tr><tr><td><strong>一句话</strong></td><td>用一段「具身提示词」把机器人平台与控制约定写进语言，配 DiT flow-matching 动作解码器，把操作、导航、人手轨迹压成同一个「动作-轨迹预测」问题，再用四阶段配方训出单一通才策略。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">抓取说明</p><p>arXiv 官方 HTML（<code>arxiv.org/html/2605.30280v1</code> 与 <code>v2</code>）均返回 404，abs 页也只提供 PDF 与 TeX Source；本文正文经 <code>ar5iv.labs.arxiv.org/html/2605.30280</code> 完整获取（约 138KB），已 grep 方法名核验。frontmatter 的标题与作者以 abs 页 v2 元数据为准。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>具身模型的现状是碎片化的：操作模型围绕桌面或灵巧手训练，导航模型围绕室内 waypoint 预测设计，人类第一视角数据给的是手腕与手部轨迹而不是机器人指令。这些任务在表面上差异极大——观测格式、控制频率、预测视界、动作维度、评测协议全都不同——于是每换一个任务族或一台机器人就要重开一个模型，具身学习没法像视觉语言预训练那样靠一份混合语料整体扩张。</p><p>本文要问的是一个很朴素的问题：<strong>这些异构的具身决策问题能不能被压进同一个 VLA 里？</strong> 作者给出的观察是它们共享同一个计算结构——都要以视觉观测、语言指令、本体约束为条件，预测一段在物理与语义上都对齐的未来动作或轨迹。如果这个观察成立，那么&quot;统一&quot;带来的不只是工程上的省事：一份语料里的空间接地、指代消解、指令跟随能力可以在任务族之间共享，导航的长时序指令跟随可以反哺操作的多步理解。价值在于把具身数据从&quot;每个平台一小堆&quot;变成&quot;可以合并计算的一大堆&quot;。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>VLM 一侧（Qwen-VL 系列、Gemini 等）已经把开放世界视觉理解与语言接地推得很远；扩散/流匹配策略（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 等）也已经证明能建模连续高维动作分布。但把二者拼起来的系统大多被锁死在一个窄任务族里。跨本体这一侧，Open X-Embodiment/RT-X 一脉的做法是把多机器人数据混起来训，但动作空间的统一往往靠离散 token 或按本体分头，前者牺牲精度与频率，后者让&quot;统一&quot;停留在共享骨干而不是共享动作空间。</p><p>论文点出的关键缺口不是&quot;没人做过多本体&quot;，而是<strong>统一的接口在哪一层</strong>。给每个本体配一个私有投影头（Multi-MLP）或把所有本体的动作维拼成一个大向量（Concatenation），模型结构就随本体数线性膨胀，新增平台要改架构。反过来强行把所有本体压进同一个物理动作语义空间又不成立——7 自由度臂和 29 自由度全身控制根本不是一回事。本文的定位是：<strong>张量接口与掩码方案统一，物理语义不统一</strong>，后者交给一段文本提示去承载。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>只用当时已有的东西推：第一步观察，一条语言指令加一句&quot;这台机器人是双臂、带腰、控制频率 30 Hz、预测 16 步&quot;其实已经把任务意图和控制约定压缩得很紧了，几十个 token；而对应的动作轨迹是几千个高维数值。第二步，这个维度落差意味着从描述到轨迹本质上是一个<strong>结构化解压问题</strong>。第三步，考虑训练的起点：VLM 骨干已经被大规模预训练过，DiT 动作解码器是随机初始化的，两者进入优化时状态极不对称——朴素联合训练会让新生解码器的噪声梯度扰动预训练表征，同时每一步都要付出编码图像的算力，而这些算力在解码器还没学会动作结构时是浪费的。</p><p>把这两点合起来，一个很自然的做法出现了：<strong>先在没有图像的情况下，只用语言与具身提示训练解码器</strong>，逼它把动作先验建成&quot;由语言索引&quot;的形式；等这个先验建好，再引入视觉做接地。这就是 T2A 阶段的来历。后面三个阶段各自补一个前一阶段没解决的缺口：CPT 补视觉接地、SFT 补下游分布对齐、RL 补&quot;模仿目标无法直接优化闭环成功率&quot;。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>不同机器人之间真正难统一的不是数值张量，而是<strong>控制约定的语义</strong>——同样一串 16 个数，在这台机器上是末端位姿增量，在那台机器上是关节角绝对值。既然骨干已经是一个很强的语言模型，那就把控制约定写成一句话让它读，而不是设计新的架构去编码它。张量层面只需要一个共享的零填充接口，语义层面由提示词区分。这样新增一个平台就只是新增一句话，模型结构一个字都不用改。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以&quot;在 ALOHA 双臂上按颜色顺序叠碗&quot;为例，端到端流程是：</p><ul><li><strong>模型</strong>。骨干是 Qwen3.5-4B（原生多模态、早融合，视觉 token 直接插进文本流；多数层用门控线性注意力、间隔插入分组查询 softmax 注意力）。动作专家是单流 DiT 风格的流匹配策略，约 1.15B 参数（16 个 DiT block 各 70.8M 共 1.13B，其余为动作投影 MLP 4.9M、VLM 隐状态到 DiT 通道的线性层 3.9M、timestep embedding 2.8M、输出 AdaLN 调制 4.7M）。做法是把 VLM 隐状态与带噪动作块拼成一条序列走联合自注意力，用 AdaLN 做 timestep 条件，RoPE 与骨干对齐。</li><li><strong>具身提示</strong>。每条样本前置一句模板：<em>The robot is {robot_tag} with {single arm / dual arms}[, waist][, and mobile base]. The control frequency is {FPS} Hz. Please predict the next {chunk_size} control actions to execute the following task: {instruction}.</em> 这是模型获知平台控制语义的<strong>唯一</strong>接口。</li><li><strong>统一表示</strong>。每条样本贡献一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7252em;vertical-align:-0.0391em;"></span><span class="mord mathbf" style="margin-right:0.0288em;">Y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span></span></span></span></span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 是固定视界、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 是所有控制模式共享的通道数；维度不足的本体右填充零，各自只读自己的前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 维（Zero-Padding 方案，参数量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord">2</span><span class="mord mathnormal">h</span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">a</span><span class="mtight">x</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，小于另两种设计）。</li><li><strong>四阶段训练</strong>。Stage I（T2A）冻结 VLM、只训 DiT，<strong>刻意不给图像</strong>，让它做纯语言到动作的解压器；Stage II（CPT）解冻两侧，在异构混合语料上做视觉接地；Stage III（SFT）从 CPT 分两路，一路多任务 SFT（VQA、空间接地、操作、导航，按本体与任务平衡采样），一路在自采遥操作数据上做真机 SFT；Stage IV（RL）<strong>只在 SimplerEnv 里</strong>用稀疏二值成功奖励做闭环优化，产出 Qwen-VLA-Instruct。</li><li><strong>预训练语料</strong>（按采样权重）：机器人操作轨迹 74.2%、导航轨迹 7.5%、人类第一视角轨迹 6.0%、自建合成仿真轨迹 3.7%、通用视觉语言数据 3.4%、2D 空间接地 2.5%、自动驾驶 VQA 2.4%、细粒度具身动作 caption 0.2%。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>动作侧是标准的条件流匹配：在时间步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 上把干净动作与高斯噪声线性插值，网络回归速度场，推理时几步 Euler 积分。本文真正有内容的数学讨论在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span> 的选择上，这一点值得展开。</p><p>流匹配训练时 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 决定了哪一段噪声水平拿到梯度。标准做法用 Beta 分布，把密度压向干净端（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 小），这在有强条件信号时是合理的：条件已经把答案框得很窄，剩下的工作是精修细节。但 T2A 阶段<strong>没有任何视觉条件</strong>，解码器手里只有一句话。此时把梯度压在干净端等于要求它从语言直接还原精确轨迹，而语言本身并不包含那么多信息；把梯度挪到中间噪声水平（Sigmoid-Normal 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 中段取峰）反而对应&quot;从粗到细地把语言映射到动作分布的哪个区域&quot;这个真正可学的结构。作者的消融正好印证这个读法：T2A 用 Sigmoid-Normal、SFT 用 Beta 得到 71.1%；T2A 换回 Beta 掉到 65.4%（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">5.7</span></span></span></span> pp）；SFT 换成 Sigmoid-Normal 掉到 62.8%（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">8.3</span></span></span></span> pp）；两阶段都用 Beta 只有 59.4%。可以推断，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span> 的最优形状实际上是<strong>条件信息量的函数</strong>——条件越弱，信噪比最有信息的区间越靠中段。</p><p>投影设计一侧有一个简单但有用的参数量论证：Multi-MLP 与 Concatenation 都需要 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0497em;vertical-align:-0.2997em;"></span><span class="mord">2</span><span class="mord mathnormal">h</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.162em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 个投影参数，Zero-Padding 只需要 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord">2</span><span class="mord mathnormal">h</span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">a</span><span class="mtight">x</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">a</span><span class="mtight">x</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0497em;vertical-align:-0.2997em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.162em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 恒成立，因此在本体数增加时前两者线性膨胀、后者不变。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：一个通才能不能打过一堆专才？</strong> 在 LIBERO / RoboCasa-GR1 / Simpler-WidowX / RoboTwin-2.0 四个基准上比较（动作块长度统一 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">16</span></span></span></span>）。Qwen-VLA-Instruct 拿到 97.9 / 56.7 / 73.7 / 86.1（Easy）/ 87.2（Hard）。结论需要按列读：LIBERO 上 97.9 <strong>低于</strong> ABot-M0 的 98.6，RoboCasa-GR1 上 56.7 也<strong>低于</strong> ABot-M0 的 58.3；真正明确领先的是 Simpler-WidowX（73.7 vs StarVLA-OFT 64.6）与 RoboTwin 两列（86.1/87.2 vs ABot-M0 86.0/85.0）。论文的表述&quot;surpasses the majority of specialist baselines&quot;是准确的，但不等于全面 SOTA。</p><p><strong>问题二：每个训练阶段各贡献多少？</strong> 表 11 逐级叠加：CPT 的 Simpler/RoboCasa/RoboTwin-E/RoboTwin-H/LIBERO/SimplerOOD/DOMINO-SR 分别是 64.3/40.4/64.3/66.4/90.8/25.3/21.1，加 SFT 变成 70.8/56.0/86.3/87.1/97.8/31.6/25.7，再加 RL 变成 73.7/56.7/86.1/87.2/97.9/32.0/26.6。也就是说，<strong>绝大部分增益来自多任务 SFT，RL 只在其 rollout 采集环境 SimplerEnv 上有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">2.9</span></span></span></span> pp 的实质提升，其余基准的变化在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">±</span><span class="mord">0.7</span></span></span></span> pp 内，RoboTwin-Easy 甚至从 86.3 略降到 86.1</strong>。作者把这解读为&quot;RL 收益没有局限在训练环境&quot;，更谨慎的读法是&quot;RL 至少没有破坏其他环境&quot;。</p><p><strong>问题三：统一本体到底有没有正迁移？</strong> 表 10 是全文最干净的对照：Bridge 单本体训 62.8，三种共训投影分别 63.3 / 63.0 / 63.0；Robocasa 单本体训 53.4，共训 52.1 / 52.8 / 53.2。结论是<strong>共训与单训基本持平，既没有明显正迁移也没有明显干扰</strong>。视觉语言数据的作用则更有分辨力：Libero 与 Simpler-WidowX 上 VLA-only 与 VL+VLA 几乎相同，而 RoboCasa-GR1 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">51.1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">56.0</span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">4.9</span></span></span></span>）、RoboTwin-2.0 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">81.8</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">86.4</span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">4.6</span></span></span></span>）——增益集中在需要细粒度物体识别与组合指令解析的基准。</p><p><strong>问题四：预训练在真机上值多少？</strong> ALOHA 双臂上做同架构对照：从零训的 in-domain 平均 48.5%、OOD 平均 36.2%；从 Qwen-VLA-Base 微调的分别是 83.6% 与 76.9%（对照 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是 71.6% 与 41.5%，GR00T N1.6 是 28.6% 与 25.4%）。OOD 五档里位置泛化最低（53.8%），背景与指令泛化最高（80.8% / 84.6%）。</p><p><strong>问题五：能否零样本迁到动态操作？</strong> 在 DOMINO 的 35 个套件上零样本评测，Instruct 拿到 SR 26.6% / MS 39.5，高于所有在 DOMINO 上微调过的方法（最好的 PUMA 是 17.2 / 35.0）。另外 SimplerEnv-OOD（只在 Bridge 简单抓放上微调，评测六个未见任务类型）平均 32.0% vs <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 12.6%，其中 MoveRight 与 PlaceNear 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 完全为 0。</p><p><strong>状态条件消融</strong>：RoboTwin 上不给本体状态 88.7/87.4，把关节角离散成 256 bin 写进 prompt 得 89.3/88.7，把连续状态直接喂 DiT 得 89.4/88.3。收益最多 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">1.3</span></span></span></span> pp，因此最终配方<strong>不使用本体状态</strong>，具身提示词是唯一的平台特定输入。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：异构具身任务共享同一个计算结构，可以被写成同一个&quot;动作-轨迹预测&quot;问题。统一不必发生在物理动作语义层，只需要统一张量接口（零填充）并把控制约定写进一段文本提示。DiT 动作解码器与 VLM 骨干进入训练时状态极不对称，先做一个无视觉的&quot;语言到动作解压&quot;预训练再引入图像，可以把下游成功率从 60.9% 抬到 71.1%。四阶段配方里绝大部分下游收益来自多任务 SFT，RL 只在采样环境上有实质增益。共训相对单本体训练基本持平——统一的价值是&quot;不付代价&quot;，而不是&quot;有正迁移&quot;。</p><p><strong>3 句话版</strong>：把机器人平台与控制约定写成提示词，就能让一个动作解码器服务所有本体而不改架构。先无视觉训练动作先验、再做视觉接地的分阶段配方，比朴素联合训练稳定且省算力。真机上大规模具身预训练的价值主要体现在 OOD（36.2% → 76.9%），而不是 in-domain 精度。</p><p><strong>1 句话版</strong>：具身模型的统一接口应该是语言，不是新的架构。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的一条是：<strong>一段自然语言提示词足以完整、无歧义地承载本体的控制语义，因此策略不需要任何本体状态输入。</strong> 论文把这条推到极致——最终配方连关节角都不给，理由是表 12 显示状态最多只值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">1.3</span></span></span></span> pp，并解释为&quot;多视角观测已经包含机器人当前构型，且解码器预测的是相对位移&quot;。</p><p>这个论证在它被测试的地方是成立的，但测试范围很窄。它默认末端执行器至少在一路相机里可见；一旦手被物体、被自身连杆或被容器遮挡，视觉就不再是构型的充分统计量。它也默认相对位移表示能吸收构型依赖，而这对冗余自由度（7 自由度臂的零空间、29 自由度全身控制）并不成立——同一个末端位移对应无穷多组关节运动，选哪一组恰恰依赖当前构型。RoboCasa-GR1（双臂人形、全身控制）正是全表最低的一档（56.7%），而 RoboTwin（双臂固定基座、末端可见）才是状态消融的测试场——<strong>最需要本体状态的设定恰好没有被这个消融覆盖</strong>。</p><p>更根本的是，论文<strong>从未扰动过具身提示词</strong>：没有&quot;给错平台标签&quot;、&quot;改控制频率描述&quot;、&quot;删掉具身前缀&quot;的对照。如果提示词是唯一的平台接口，那它就是唯一的单点故障，而它的敏感性完全没有被度量。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、不需要复现 4B 骨干的验证，直接针对 §9：</p><ol><li>取任意开源的多本体 VLA（或用 LIBERO + RoboTwin 两个本体自训一个小模型），复现&quot;零填充接口 + 具身提示词&quot;的最小版本。</li><li>做三组推理期干预，<strong>不重新训练</strong>：(a) 保持提示词正确；(b) 把提示词换成另一个本体的（双臂换单臂、频率改成 2 倍）；(c) 整段删掉具身前缀只留指令。</li><li>度量三件事：成功率、动作块的 L2 幅度、以及动作在被填充为零的那些通道上的输出是否仍然为零。</li><li>判据：如果 (b)(c) 相对 (a) 成功率几乎不掉，说明提示词在推理期是<strong>惰性</strong>的——模型实际上是靠图像里的机器人外观区分本体，&quot;语言即接口&quot;的叙事需要改写；如果掉得很厉害，则应进一步测提示词的措辞鲁棒性（同义改写、语序变化），因为一个只对固定模板生效的接口在部署时同样脆弱。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者的立场，最有力的攻击是指出**&quot;单一通才超过一群专才&quot;这个比较并不对称**。Qwen-VLA-Instruct 的多任务 SFT 就包含了这四个基准的下游数据，此外还在 SimplerEnv 上做了 RL；而每个 specialist 只在自己那一个基准上微调。真正&quot;没有 per-benchmark adaptation&quot;的模型是 Qwen-VLA-Base，它的成绩是 90.8 / 40.4 / 64.3 / 64.3 / 66.4——在 LIBERO、RoboCasa、RoboTwin 三处都明显低于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 ABot-M0。因此表 4 度量的与其说是&quot;统一 vs 专用&quot;，不如说是&quot;一个模型看了四份下游数据 vs 四个模型各看一份&quot;。</p><p>而作者自己的表 10 恰好堵死了&quot;统一带来正迁移&quot;这条退路：共训 63.3/52.1 与单训 62.8/53.4 在噪声内，Robocasa 上共训甚至略低。把这两点合起来，一个完整的替代解释成立：<strong>Qwen-VLA-Instruct 的领先来自更强的骨干（Qwen3.5-4B）、T2A 带来的更好初始化、以及更大的下游 SFT 数据量，而不是来自&quot;统一动作空间&quot;这一设计本身。</strong> 判决实验是把 SFT 数据切成四份，训四个&quot;专用版 Qwen-VLA&quot;（同骨干、同 T2A、同 CPT，只在各自基准上 SFT），与通才逐列比较；如果专用版全面持平或更好，&quot;统一&quot;的贡献就只剩工程便利性。</p><p>还有两处跨论文的可比性问题值得记下。同批的 <a href="/notes/papers/2606.14409">Hy-Embodied-0.5-VLA</a> 在同一个 RoboTwin 2.0 榜上引用了同一批&quot;官方报告&quot;数字：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 65.9/58.4、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 82.7/76.8、Qwen-VLA 86.1/87.2 三者逐位一致，说明两篇的两列是同一件东西；但 <strong>ABot-M0 在本文里是 86.0/85.0，在那篇里是 81.2/80.4</strong>，必有一处引用有误。另外本文把这两列称作 &quot;Easy / Hard difficulty tiers&quot;，而该篇称作 &quot;Clean / Randomized&quot;——按后者的口径才解释得通为什么本文自己的 Hard（87.2）<strong>高于</strong> Easy（86.1）：域随机化并不必然比干净设置更难。可以推断本文的 Easy/Hard 命名不准确。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：本文的统一停在&quot;输入侧的语言接口 + 输出侧的张量接口&quot;，而共训无正迁移这一结果说明模型内部并没有学到跨本体共享的<strong>动作结构</strong>——它更像是学会了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 套彼此独立的映射，恰好共用一套参数。零填充接口尤其把这一点固化了：不同本体的动作被硬绑在不同的通道下标上，通道之间没有任何物理对应关系被告知给模型。</p><p><strong>新的 framing</strong>：不要把&quot;统一&quot;当作接口问题，当作<strong>表示学习问题</strong>——学一个本体无关的潜动作空间，让每台机器人只负责&quot;从潜动作到自己关节空间&quot;的解码。这与本文的方向恰好相反：本文把本体差异推给语言，这里主张把本体差异推给一个可学习的、显式带物理语义的编解码器。相邻领域现成的工具有两类：多任务/多物种神经科学里的 latent alignment（把不同个体的神经记录对齐到共享潜空间，典型做法是共享动力学 + 个体特异的读出矩阵），以及计算机图形学里的运动重定向（skeleton-agnostic motion representation）。</p><p><strong>第一个实验</strong>：在现有 CPT 检查点上冻结骨干，把 Zero-Padding 投影换成&quot;共享潜动作码本 + 每本体一个线性读出&quot;，用同样的数据重跑 CPT，然后做一件本文做不了的事——<strong>跨本体零样本</strong>：拿一个在训练中从未出现的本体（比如把 RoboTwin 的双臂配置改成单臂），只提供它的读出矩阵（可由 100 条轨迹最小二乘拟合，不动骨干），测成功率。如果这个设定下成绩显著高于&quot;新增一句提示词 + 零填充&quot;的对照，就证明共享潜动作空间承载了真正的跨本体结构；如果两者持平，则说明跨本体迁移的瓶颈根本不在动作表示，而在视觉与语义接地——那本身就是一个更值得写下来的结论。</p>',48)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
